-- Wave fronts and the Director's Stage reset: new Balance Config fields shared.spawn.{frontShare,frontArc,frontEvery,
-- frontTurn,lull,lullSpawn,frontRecycle,pincer,pincerArc} (most monsters come from one side at a time, swarms as two
-- arcs) and shared.director.stageReset. Patched into the live config_schema so publish_config accepts them; their
-- defaults keep the current behaviour (all around, full rings, Director carried over) until an admin publishes others.
update public.config_schema set schema = jsonb_set(jsonb_set(schema,
  '{properties,shared,properties,spawn}',
  $j${"description":"Spawner","default":{},"type":"object","properties":{"base":{"default":1.4,"description":"Spawns/s at stage start","type":"number","minimum":0,"maximum":14},"prog":{"default":3.4,"description":"Extra spawns/s at stage end","type":"number","minimum":0,"maximum":34},"stageGrowth":{"default":0.35,"description":"Spawn rate growth per stage","type":"number","minimum":0,"maximum":1},"perMate":{"default":0.6,"description":"Spawn multiplier per extra living player","type":"number","minimum":0,"maximum":10},"cap":{"default":320,"description":"Enemy cap","type":"number","minimum":10,"maximum":2000},"eliteChance":{"default":0.012,"description":"Elite chance per stage","type":"number","minimum":0,"maximum":1},"swarmFirst":{"default":16,"description":"First swarm ring (s)","type":"number","minimum":0,"maximum":600},"swarmEvery":{"default":18,"description":"Swarm ring interval (s)","type":"number","minimum":0,"maximum":600},"swarmEveryBloodMoon":{"default":10,"description":"Swarm interval in Blood Moon (s)","type":"number","minimum":0,"maximum":600},"swarmBase":{"default":16,"description":"Enemies per swarm ring","type":"number","minimum":0,"maximum":500},"swarmPerStage":{"default":6,"description":"Extra ring enemies per stage","type":"number","minimum":0,"maximum":100},"swarmCap":{"default":340,"description":"Enemy cap during swarm","type":"number","minimum":10,"maximum":2000},"capMobile":{"default":240,"description":"Enemy cap on phones/tablets","type":"number","minimum":10,"maximum":2000},"swarmCapMobile":{"default":260,"description":"Enemy cap during swarm on phones/tablets","type":"number","minimum":10,"maximum":2000},"edge":{"default":14,"description":"Spawn distance beyond the view edge","type":"number","minimum":0,"maximum":140},"ringEdge":{"default":10,"description":"Swarm ring distance beyond the view edge","type":"number","minimum":0,"maximum":100},"despawn":{"default":0.95,"description":"Recycle distance (× view diagonal)","type":"number","minimum":0,"maximum":10},"frontShare":{"default":0,"description":"Share of monsters that come from the wave front instead of anywhere around (0 = all around)","type":"number","minimum":0,"maximum":1},"frontArc":{"default":100,"description":"Wave front width (degrees)","type":"number","minimum":10,"maximum":360},"frontEvery":{"default":9,"description":"Seconds before the wave front moves to another side","type":"number","minimum":1,"maximum":120},"frontTurn":{"default":90,"description":"The next wave front turns at least this many degrees","type":"number","minimum":0,"maximum":180},"lull":{"default":0,"description":"Quiet seconds each time the wave front moves (0 = none)","type":"number","minimum":0,"maximum":600},"lullSpawn":{"default":0.35,"description":"Spawn rate × during the quiet seconds","type":"number","minimum":0,"maximum":1},"frontRecycle":{"default":0,"description":"Monsters left far behind reappear on the wave front (1) or anywhere around (0)","type":"number","minimum":0,"maximum":1},"pincer":{"default":0,"description":"Swarms on normal Stages come as two arcs from the wave front's sides (1) or a full ring (0)","type":"number","minimum":0,"maximum":1},"pincerArc":{"default":100,"description":"Width of each swarm arc (degrees)","type":"number","minimum":10,"maximum":180}}}$j$::jsonb),
  '{properties,shared,properties,director}',
  $j${"description":"Director (adaptive pressure)","default":{},"type":"object","properties":{"start":{"default":1,"description":"Starting value","type":"number","minimum":0,"maximum":5},"min":{"default":0.7,"description":"Minimum","type":"number","minimum":0,"maximum":5},"max":{"default":2.4,"description":"Maximum","type":"number","minimum":0,"maximum":5},"rise":{"default":0.06,"description":"Rise per second while cruising","type":"number","minimum":0,"maximum":10},"riseHp":{"default":0.75,"description":"Cruising: HP above this fraction","type":"number","minimum":0,"maximum":1},"riseCalm":{"default":6,"description":"Cruising: seconds without being hurt","type":"number","minimum":0,"maximum":600},"drop":{"default":0.2,"description":"Drop per second while struggling","type":"number","minimum":0,"maximum":10},"dropHp":{"default":0.4,"description":"Struggling: HP below this fraction","type":"number","minimum":0,"maximum":1},"hurtDrop":{"default":0.03,"description":"Drop per second right after a hit","type":"number","minimum":0,"maximum":10},"hurtWindow":{"default":2,"description":"Seconds counted as right after a hit","type":"number","minimum":0,"maximum":600},"stageReset":{"default":0,"description":"A new Stage moves the Director this share of the way back to its starting value (0 = keeps it)","type":"number","minimum":0,"maximum":1}}}$j$::jsonb)
where id = 1;
